   "heading": "FMOD_STUDIO_LOAD_MEMORY_MODE",
   "notes": [
    "No Haxe equivalent. StudioSystem.loadBankMemory always uses the copying mode, since the binding cannot pin a Haxe buffer for the bank's lifetime."
   ],
   "shape": null,
